def is_anagram(s, t):
    if len(s) != len(t):
        return False
    cnt = [0] * 26
    for ch in s:
        cnt[ord(ch) - ord('a')] += 1
    for ch in t:
        cnt[ord(ch) - ord('a')] -= 1
    return all(c == 0 for c in cnt)

