from collections import deque

def longest_subarray(nums, limit):
    mx, mn = deque(), deque()
    l = best = 0
    for r, x in enumerate(nums):
        while mx and mx[-1] < x:
            mx.pop()
        mx.append(x)
        while mn and mn[-1] > x:
            mn.pop()
        mn.append(x)
        while mx[0] - mn[0] > limit:
            if nums[l] == mx[0]:
                mx.popleft()
            if nums[l] == mn[0]:
                mn.popleft()
            l += 1
        best = max(best, r - l + 1)
    return best

